python3 -I -c "
import pyarrow.parquet as pq, pyarrow.compute as pc, glob
pat = 'D-32-07-M-00100'
for f in sorted(glob.glob('*.parquet')):
    t = pq.read_table(f)
    for col in t.column_names:
        if pa_type := (t.schema.field(col).type):
            if str(pa_type) == 'string':
                m = pc.match_substring(t[col], pat)
                n = pc.sum(m.cast('int64')).as_py() or 0
                if n: print(f, col, 'matches:', n)
    print('checked', f)
"

